def english(text):
    for source,target in sorted(TRANSLATIONS.items(),key=lambda p:len(p[0]),reverse=True):
        text=text.replace(source,target)
    return text

def presentation(value,key=""):
    if isinstance(value,list): return [presentation(v,key) for v in value]
    if isinstance(value,dict): return {k:presentation(v,k) for k,v in value.items()}
    if isinstance(value,str) and key in ("error","notice","dependencyNotice","detail"):
        return english(value)
    return value
